-- Operational policy v3 preserves the approved five weights and adds configurable rubric criteria/modifier/decay slots.
update community_impact_score_policy_version set status='superseded' where version=2 and status='active';
insert into community_impact_score_policy_event(policy_version_id,event_code,rationale,metadata)
select id,'superseded','Replaced by operational initial baseline v3 with policy-configured rubric criteria, modifiers and decay rules.',jsonb_build_object('replacedByVersion',3)
from community_impact_score_policy_version where version=2
and not exists(select 1 from community_impact_score_policy_event e where e.policy_version_id=community_impact_score_policy_version.id and e.event_code='superseded');

insert into community_impact_score_policy_version(version,schema_version,policy_hash,policy,status,evaluation_only,public_score_enabled,rationale,change_summary,created_by)
values(3,1,'4cb764433a4a8652ee98dc02497169f11ccd689d727437ccac039c58d4b1f719','{"mode":"evaluation","publicScoreEnabled":false,"dimensions":[{"key":"measurable_community_outcomes","label":"Measurable community outcomes","weight":30,"minimumEvidenceQuality":"adequate","ratings":{"min":0,"max":5,"step":1},"criteria":["Documented result or change","Reach and beneficiary evidence","Evidence connecting contribution to outcome"],"measurementRules":{"requiresVerifiedOutcome":true,"followUpDays":0}},{"key":"quality_and_significance","label":"Quality and significance","weight":25,"minimumEvidenceQuality":"adequate","ratings":{"min":0,"max":5,"step":1},"criteria":["Reliability and strength of evidence","Significance and scope of contribution","Quality of delivery"],"measurementRules":{"requiresEvidenceReferences":true}},{"key":"verified_contribution_responsibility","label":"Verified contribution and responsibility","weight":20,"minimumEvidenceQuality":"adequate","ratings":{"min":0,"max":5,"step":1},"criteria":["Verified contributor identity and role","Attributable contribution share","Responsibility actually performed"],"measurementRules":{"requiresVerifiedAttribution":true}},{"key":"sustainability","label":"Sustainability","weight":15,"minimumEvidenceQuality":"adequate","ratings":{"min":0,"max":5,"step":1},"criteria":["Durability or continuation evidence","Maintenance or ownership plan","Follow-up evidence where available"],"measurementRules":{"followUpDays":0,"requiresFollowUpEvidence":false}},{"key":"collaboration_knowledge_sharing","label":"Collaboration and knowledge sharing","weight":10,"minimumEvidenceQuality":"adequate","ratings":{"min":0,"max":5,"step":1},"criteria":["Recipient or partner confirmation","Knowledge shared or transferred","Collaboration quality and reciprocal contribution"],"measurementRules":{"requiresRecipientConfirmation":true}}],"calculation":{"basePoints":100,"rounding":"4dp","roleFactors":{"lead":1,"co_lead":1,"contributor":1,"mentor":1,"reviewer_organizer":1,"partner_organization":1,"other":1},"minimumEvidenceQuality":"adequate","evidenceQualityRank":{"insufficient":0,"limited":1,"adequate":2,"strong":3,"exceptional":4},"minimumOutcomeMaturity":"output","outcomeMaturityRank":{"activity":0,"output":1,"outcome":2,"sustained_impact":3},"requiredAssessmentStatus":"approved","requiredClaimStatus":"verified","sourceCaps":{},"categoryCaps":{},"periodCaps":{},"diminishingReturns":[],"modifiers":[],"decayRules":[],"eligibleSourceTypes":["serve_community_participation","offline_completed_project","mentorship","professional_service","employment_referral","network_plus_collaboration","network_plus_partnership","historical_contribution"]},"publication":{"enabled":false,"consentRequired":true,"minimumGroupSize":5}}'::jsonb,'active',true,false,
'Initial docs/62 baseline with policy-configured rubric criteria, measurement rules, modifiers and decay slots; unchanged approved weights; private evaluation only.',
'Operational scoring policy v3; preserves the approved five-dimension weights and makes rubric/modifier/decay configuration explicit.',null)
on conflict(version) do nothing;

update community_impact_score_active_policy set policy_version_id=(select id from community_impact_score_policy_version where version=3),activated_by=null,activated_at=now() where singleton=true;
insert into community_impact_score_policy_event(policy_version_id,event_code,rationale,metadata)
select id,'activated','Activated the initial docs/62 five-dimension policy with configurable rubric criteria and modifiers for private evaluation only.',jsonb_build_object('version',3,'publicScoreEnabled',false)
from community_impact_score_policy_version where version=3
and not exists(select 1 from community_impact_score_policy_event e where e.policy_version_id=community_impact_score_policy_version.id and e.event_code='activated');
